INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_001', 'HR-001 Total Active Headcount (Persons)', 'Number of active employees at the end of the period Target: Aligned with headcount plan. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employee WHERE status = ''Active''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_002', 'HR-002 Headcount vs Filled Positions (%)', 'Ratio of filled positions to total active positions (Vacant + Filled) Target: ≥ 95%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Filled'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Filled'',''Vacant'')), 0), 2) AS value FROM reporting.position", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_003', 'HR-003 Vacancy Rate (%)', 'Percentage of vacant positions Target: ≤ 5%. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Vacant'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Filled'',''Vacant'')), 0), 2) AS value FROM reporting.position", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_004', 'HR-004 Frozen Position Count (Positions)', 'Number of frozen positions Target: Per efficiency policy. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.position WHERE status = ''Frozen''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_005', 'HR-005 Span of Control (Ratio)', 'Average number of direct reports per supervisor Target: 5–10 subordinates. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COUNT(*)::numeric / NULLIF(COUNT(DISTINCT reports_to), 0), 2) AS value FROM reporting.employee WHERE status = ''Active'' AND reports_to IS NOT NULL", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_006', 'HR-006 Manager Ratio (%)', 'Percentage of managerial positions out of total positions Target: 10–15%. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE is_manager_position)) / NULLIF(COUNT(*) FILTER (WHERE status <> ''Closed''), 0), 2) AS value FROM reporting.position WHERE status <> ''Closed''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_007', 'HR-007 Gender Composition', 'Percentage of female employees in active headcount Target: Per D&I target. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(gender, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.employee WHERE status = ''Active'' GROUP BY 1 ORDER BY 2 DESC", "parameters": [], "visual": {"type": "pie", "xColumn": "label", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_009', 'HR-009 Average Tenure (Years)', 'Average length of service of active employees Target: ≥ 3 years. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG((CURRENT_DATE - COALESCE(original_hire_date, hire_date)) / 365.25), 1) AS value FROM reporting.employee WHERE status = ''Active''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_010', 'HR-010 Employment Status Composition', 'Percentage of employees by employment type (Permanent/Fixed-term Contract/etc.) Target: Per contract employment policy. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(employment_type, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.employee WHERE status = ''Active'' GROUP BY 1 ORDER BY 2 DESC", "parameters": [], "visual": {"type": "pie", "xColumn": "label", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_011', 'HR-011 Employees on Probation (Persons)', 'Number of active employees whose probation end date has not passed Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employee WHERE status = ''Active'' AND probation_end_date >= CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_012', 'HR-012 Probation Overdue (Orang)', 'Karyawan yang probation sudah lewat tetapi belum ada JobChange ''Probation completed'' Target: 0. Arah: Turun. Snapshot kondisi saat ini; tidak dipengaruhi filter tanggal.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employee e WHERE e.status = ''Active'' AND e.probation_end_date < CURRENT_DATE AND NOT EXISTS (SELECT 1 FROM reporting.job_change j WHERE j.employee = e.name AND j.docstatus = 1 AND j.change_reason = ''Probation completed'') AND e.probation_end_date >= CURRENT_DATE - 365", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_016', 'HR-016 Emergency Contact Completeness (%)', 'Percentage of active employees with at least 1 emergency contact Target: 100%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.employee_emergency_contacts c WHERE c.parent = e.name))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.status = ''Active''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_018', 'HR-018 Education Profile (%)', 'Percentage of employees with Bachelor''s degree or higher Target: Per job profile. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.employee_education x WHERE x.parent = e.name AND x.level IN (''Bachelor'',''Master'',''Doctorate'')))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.status = ''Active''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_019', 'HR-019 Revenue per Employee (IDR/person)', 'Revenue per active employee Target: Increase YoY. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE((SELECT SUM(si.total * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End), 0) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 0) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_020', 'HR-020 Labour Cost to Revenue (%)', 'Labor costs compared to total revenue Target: Industry standard. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT SUM(r.total_gross + r.total_employer_contributions) FROM reporting.payroll_run r WHERE r.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(si.total * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_021', 'HR-021 Organization Units Without Manager (Units)', 'Active organization units with an empty manager field Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.organization_unit WHERE is_active AND manager IS NULL", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_022', 'HR-022 Organization Units Without Cost Center (Units)', 'Active organization units not yet mapped to a cost center Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.organization_unit WHERE is_active AND cost_center IS NULL", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_023', 'HR-023 Organization Structure Depth (Levels)', 'Number of hierarchy levels from top to bottom organization unit Target: ≤ 6 levels. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "WITH RECURSIVE t AS (SELECT name, 1 AS lvl FROM reporting.organization_unit WHERE is_active AND parent_org_unit IS NULL UNION ALL SELECT o.name, t.lvl + 1 FROM reporting.organization_unit o JOIN t ON o.parent_org_unit = t.name WHERE o.is_active AND t.lvl < 50) SELECT MAX(lvl) AS value FROM t", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_024', 'HR-024 Positions With Dotted Line (%)', 'Percentage of positions with matrix reporting lines Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.position_dotted_lines d WHERE d.parent = p.name))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.position p WHERE p.status <> ''Closed''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_027', 'HR-027 Job Profiles Without Default Grade (Profiles)', 'Active job profiles without a default grade configured Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.job_profile WHERE is_active AND default_grade IS NULL", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_028', 'HR-028 Promotion Rate (%)', 'Percentage of employees promoted within the period Target: 5–10% per year. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Promotion'' AND effective_date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_029', 'HR-029 Internal Mobility Rate (%)', 'Transfers and rotations compared to headcount Target: ≥ 8% per year. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.job_change WHERE docstatus = 1 AND change_reason IN (''Transfer'',''Rotation'') AND effective_date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_030', 'HR-030 Demotion Count (Cases)', 'Number of demotions Target: Minimal. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Demotion'' AND effective_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_031', 'HR-031 Employment Status Conversion (Persons)', 'Contract employees converted to permanent status Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Employment status change'' AND new_employment_type = ''Permanent (PKWTT)'' AND effective_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_032', 'HR-032 Average Time Since Last Job Change (Months)', 'Average months since last job change date Target: ≤ 36 months. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG((CURRENT_DATE - COALESCE(last_job_change_date, hire_date)) / 30.44), 1) AS value FROM reporting.employee WHERE status = ''Active''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_033', 'HR-033 Employees Affected by Reorganization (Persons)', 'Number of employees affected by reorganization Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.job_change WHERE docstatus = 1 AND change_reason = ''Reorganization'' AND effective_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_034', 'HR-034 Expiring Contracts (Contracts)', 'Active contracts ending within X days (X = HRSettings.contract_expiry_reminder_days) Target: All followed up. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employment_contract c WHERE c.docstatus = 1 AND c.status = ''Active'' AND c.end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + COALESCE((SELECT MAX(contract_expiry_reminder_days) FROM reporting.hrsettings), 30)::int", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_035', 'HR-035 Expired Contracts Without Follow-up (Contracts)', 'Expired contracts where the employee remains active without a successor contract Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employment_contract c JOIN reporting.employee e ON e.name = c.employee WHERE c.docstatus = 1 AND (c.status = ''Expired'' OR (c.status = ''Active'' AND c.end_date < CURRENT_DATE)) AND e.status = ''Active'' AND NOT EXISTS (SELECT 1 FROM reporting.employment_contract n WHERE n.employee = c.employee AND n.docstatus = 1 AND n.status = ''Active'' AND COALESCE(n.end_date, DATE ''9999-12-31'') >= CURRENT_DATE)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_036', 'HR-036 Contract Renewal Rate (%)', 'Contracts renewed compared to contracts ending Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Renewed'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Renewed'',''Expired'',''Terminated'')), 0), 2) AS value FROM reporting.employment_contract WHERE docstatus = 1 AND end_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_038', 'HR-038 Open Requisitions (Requisitions)', 'Number of job requisitions with Open status Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status = ''Open''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_039', 'HR-039 Open Openings (Persons)', 'Total unfilled job openings Target: —. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(GREATEST(openings - COALESCE(hired_count, 0), 0)), 0) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status = ''Open''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_040', 'HR-040 Requisition Fill Rate (%)', 'Filled openings compared to total openings Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(COALESCE(hired_count, 0))) / NULLIF(SUM(openings), 0), 2) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status <> ''Cancelled'' AND created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_042', 'HR-042 Time to Hire (Days)', 'Days from applicant creation to Hired status Target: ≤ 30 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(e.hire_date - a.created::date), 1) AS value FROM reporting.job_applicant a JOIN reporting.employee e ON e.name = a.employee WHERE a.status = ''Hired'' AND e.hire_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_043', 'HR-043 Time to Start (Days)', 'Days from offer date to proposed start date Target: ≤ 30 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(proposed_start_date - offer_date), 1) AS value FROM reporting.job_offer WHERE workflow_state = ''Accepted'' AND offer_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_044', 'HR-044 Applicants per Opening (Applicants)', 'Average number of applicants per opening Target: ≥ 20. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(SUM(COALESCE(applicant_count, 0))::numeric / NULLIF(SUM(openings), 0), 1) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status <> ''Cancelled'' AND created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_045', 'HR-045 Screening Pass Rate (%)', 'Applicants advancing to interview or later stages Target: 20–30%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status IN (''Interview'',''Offer'',''Hired''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_applicant WHERE created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_046', 'HR-046 Interview Pass Rate (%)', 'Interviews resulting in Pass Target: 30–50%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE result = ''Pass'')) / NULLIF(COUNT(*) FILTER (WHERE result IN (''Pass'',''Fail'')), 0), 2) AS value FROM reporting.interview WHERE scheduled_at::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_047', 'HR-047 Average Interview Rating (Score 1–5)', 'Average interviewer evaluation rating Target: ≥ 3,5. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(rating::numeric), 2) AS value FROM reporting.interview WHERE rating IS NOT NULL AND scheduled_at::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_048', 'HR-048 Interview per Hire (Ratio)', 'Number of interviews conducted per hired employee Target: ≤ 6. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND((SELECT COUNT(*) FROM reporting.interview WHERE scheduled_at::date BETWEEN @Start AND @End)::numeric / NULLIF((SELECT COUNT(*) FROM reporting.job_applicant a JOIN reporting.employee e ON e.name = a.employee WHERE a.status = ''Hired'' AND e.hire_date BETWEEN @Start AND @End), 0), 1) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_049', 'HR-049 Interviews Pending Feedback (Interviews)', 'Completed interviews past schedule where result is still Pending Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.interview WHERE result = ''Pending'' AND scheduled_at < now() - interval ''2 days''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_050', 'HR-050 Offer Acceptance Rate (%)', 'Accepted offers compared to total offers extended Target: ≥ 85%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Accepted'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Accepted'',''Declined'')), 0), 2) AS value FROM reporting.job_offer WHERE offer_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_051', 'HR-051 Offer Expired (Offers)', 'Offers past expiration date without candidate decision Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.job_offer WHERE workflow_state = ''Expired'' OR (workflow_state = ''Sent'' AND valid_until < CURRENT_DATE)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_053', 'HR-053 Source of Hire Mix', 'Percentage of hires by source channel (Referral, Job portal, Agency, etc.) Target: Referral ≥ 25%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(a.source, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.job_applicant a LEFT JOIN reporting.employee e ON e.name = a.employee WHERE a.status = ''Hired'' AND COALESCE(e.hire_date, a.modified::date) BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "pie", "xColumn": "label", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_054', 'HR-054 Referral Conversion (%)', 'Referral applicants successfully hired Target: ≥ 15%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Hired'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_applicant WHERE source = ''Referral'' AND created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_055', 'HR-055 Candidate Withdrawal Rate (%)', 'Applicants withdrawing voluntarily from the hiring pipeline Target: ≤ 10%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Withdrawn'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_applicant WHERE created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_056', 'HR-056 Replacement vs New Headcount (%)', 'Proportion of replacement requisitions vs new headcount Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE reason = ''Replacement'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_057', 'HR-057 Requisition Overdue (Requisitions)', 'Open requisitions where target start date has passed Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.job_requisition WHERE docstatus = 1 AND requisition_status = ''Open'' AND target_start_date < CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_059', 'HR-059 Hiring Quality (Probation Pass Rate) (%)', 'Percentage of new hires passing probation Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.job_change j WHERE j.employee = e.name AND j.docstatus = 1 AND j.change_reason = ''Probation completed''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.hire_date BETWEEN @Start AND @End AND e.probation_end_date < CURRENT_DATE", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_060', 'HR-060 Attendance Rate (%)', 'Days present (Present, WFH, Half day) compared to scheduled working days Target: ≥ 97%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status IN (''Present'',''Work from home'')) + 0.5 * COUNT(*) FILTER (WHERE status = ''Half day'')) / NULLIF(COUNT(*) FILTER (WHERE status <> ''On leave''), 0), 2) AS value FROM reporting.attendance WHERE attendance_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_061', 'HR-061 Absenteeism Rate (%)', 'Unplanned absence days compared to scheduled working days Target: ≤ 2%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Absent'')) / NULLIF(COUNT(*) FILTER (WHERE status <> ''On leave''), 0), 2) AS value FROM reporting.attendance WHERE attendance_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_062', 'HR-062 Tardiness Rate (%)', 'Percentage of present days with late arrival exceeding grace period Target: ≤ 5%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE a.late_minutes > COALESCE(s.late_grace_minutes, 0))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.attendance a LEFT JOIN reporting.shift_type s ON s.name = a.shift_type WHERE a.status IN (''Present'',''Work from home'',''Half day'') AND a.attendance_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_063', 'HR-063 Average Late Minutes (Minutes)', 'Average minutes late per tardiness occurrence Target: ≤ 15. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(late_minutes), 1) AS value FROM reporting.attendance WHERE late_minutes > 0 AND attendance_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_064', 'HR-064 Average Daily Working Hours (Hours)', 'Average working hours per present attendance record Target: ≈ ShiftType.working_hours_per_day. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(working_hours), 2) AS value FROM reporting.attendance WHERE status IN (''Present'',''Work from home'') AND working_hours > 0 AND attendance_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_065', 'HR-065 WFH Ratio (%)', 'Work from home days compared to total present days Target: Per hybrid work policy. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Work from home'')) / NULLIF(COUNT(*) FILTER (WHERE status IN (''Present'',''Work from home'',''Half day'')), 0), 2) AS value FROM reporting.attendance WHERE attendance_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_066', 'HR-066 Missing Check-out (Occurrences)', 'Attendance records with check-in but missing check-out Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.attendance WHERE status IN (''Present'',''Work from home'',''Half day'') AND check_in IS NOT NULL AND check_out IS NULL AND attendance_date BETWEEN @Start AND LEAST(@End, CURRENT_DATE - 1)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_067', 'HR-067 Geolocation Compliance (%)', 'Check-in logs containing valid geolocation coordinates Target: ≥ 98%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(check_in_location, '''') <> '''')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.attendance WHERE check_in IS NOT NULL AND attendance_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_068', 'HR-068 Night Shift Employees (%)', 'Percentage of active employees assigned to night shifts Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE s.is_night_shift)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e LEFT JOIN reporting.shift_type s ON s.name = e.shift_type WHERE e.status = ''Active''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_069', 'HR-069 Leave Utilization Rate (%)', 'Approved leave days used compared to total leave allocation Target: 60–90%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT SUM(total_days) FROM reporting.leave_application WHERE workflow_state = ''Approved'' AND from_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(total_leaves) FROM reporting.leave_allocation WHERE docstatus = 1 AND from_date <= @End AND to_date >= @Start), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_070', 'HR-070 Average Leave Balance (Days)', 'Average remaining leave balance per employee Target: ≤ 6 days at year end. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "WITH al AS (SELECT employee, leave_type, from_date, to_date, total_leaves FROM reporting.leave_allocation WHERE docstatus = 1 AND CURRENT_DATE BETWEEN from_date AND to_date), bal AS (SELECT al.employee, al.total_leaves - COALESCE((SELECT SUM(l.total_days) FROM reporting.leave_application l WHERE l.employee = al.employee AND l.leave_type = al.leave_type AND l.workflow_state = ''Approved'' AND l.from_date BETWEEN al.from_date AND al.to_date), 0) AS remaining FROM al) SELECT ROUND(AVG(remaining), 1) AS value FROM bal", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_071', 'HR-071 Leave Liability (IDR) (IDR)', 'Estimated monetary liability of untaken leave balances Target: Decrease YoY. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "WITH al AS (SELECT a.employee, a.leave_type, a.from_date, a.to_date, a.total_leaves FROM reporting.leave_allocation a JOIN reporting.leave_type t ON t.name = a.leave_type WHERE a.docstatus = 1 AND t.is_paid AND CURRENT_DATE BETWEEN a.from_date AND a.to_date), bal AS (SELECT al.employee, GREATEST(al.total_leaves - COALESCE((SELECT SUM(l.total_days) FROM reporting.leave_application l WHERE l.employee = al.employee AND l.leave_type = al.leave_type AND l.workflow_state = ''Approved'' AND l.from_date BETWEEN al.from_date AND al.to_date), 0), 0) AS remaining FROM al) SELECT ROUND(SUM(b.remaining * s.total_earnings / 21.0), 0) AS value FROM bal b JOIN reporting.salary_assignment s ON s.employee = b.employee AND s.is_active", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_073', 'HR-073 Leave Rejection Rate (%)', 'Percentage of leave requests rejected Target: ≤ 5%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Rejected'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Approved'',''Rejected'')), 0), 2) AS value FROM reporting.leave_application WHERE from_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_074', 'HR-074 Pending Leave Requests (Requests)', 'Leave requests pending approval > 2 days Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.leave_application WHERE workflow_state = ''Pending Approval'' AND modified < now() - interval ''2 days''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_075', 'HR-075 Sick Leave Rate (%)', 'Sick leave days taken compared to working days Target: ≤ 2%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COALESCE(SUM(total_days), 0) FROM reporting.leave_application WHERE workflow_state = ''Approved'' AND (leave_type ILIKE ''%sick%'' OR leave_type ILIKE ''%sakit%'') AND from_date BETWEEN @Start AND @End) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active'') * (SELECT COUNT(*) FROM generate_series(@Start::date, @End::date, interval ''1 day'') g WHERE EXTRACT(ISODOW FROM g) < 6), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_076', 'HR-076 Unpaid Leave Days (Days)', 'Total unpaid leave days taken Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(p.unpaid_leave_days), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_078', 'HR-078 Carry-forward Ratio (%)', 'Unused leave carried forward to next fiscal year Target: ≤ 20%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(COALESCE(carry_forwarded, 0))) / NULLIF(SUM(total_leaves), 0), 2) AS value FROM reporting.leave_allocation WHERE docstatus = 1 AND from_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_079', 'HR-079 Bradford Factor (Average) (Score)', 'Absence disruption metric (frequency squared x total duration) Target: ≤ 50. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(s * s * d), 1) AS value FROM (SELECT employee, COUNT(*) AS s, SUM(total_days) AS d FROM reporting.leave_application WHERE workflow_state = ''Approved'' AND (leave_type ILIKE ''%sick%'' OR leave_type ILIKE ''%sakit%'') AND from_date BETWEEN @Start AND @End GROUP BY employee) x", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_080', 'HR-080 Total Overtime Hours (Hours)', 'Total approved overtime hours across organization Target: Within budget. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(hours), 0) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_081', 'HR-081 Overtime Hours per Employee (Hours)', 'Average overtime hours per active employee Target: ≤ 14 hours/week (regulatory limit). Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(SUM(hours) / NULLIF(COUNT(DISTINCT employee), 0), 1) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_082', 'HR-082 Overtime Cost % Salary (%)', 'Overtime premium expense compared to total gross salary Target: ≤ 5%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT SUM(e.amount) FROM reporting.payslip_earnings e JOIN reporting.payslip p ON p.name = e.parent JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End AND e.salary_component IN (SELECT overtime_component FROM reporting.payroll_settings)) / NULLIF((SELECT SUM(p.gross_earnings) FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_083', 'HR-083 Employees Exceeding Overtime Limit (Persons)', 'Employees exceeding statutory weekly or monthly overtime hours Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(DISTINCT employee) AS value FROM (SELECT employee, date_trunc(''week'', overtime_date) AS wk, SUM(hours) AS h FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End GROUP BY 1, 2) x WHERE h > 18", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_084', 'HR-084 Holiday Overtime (%)', 'Proportion of overtime worked on rest days or public holidays Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(hours) FILTER (WHERE day_type <> ''Working day'')) / NULLIF(SUM(hours), 0), 2) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_085', 'HR-085 Weighted Hours Ratio (Ratio)', 'Statutory weighted overtime hours multiplier compared to actual hours Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(SUM(weighted_hours) / NULLIF(SUM(hours), 0), 2) AS value FROM reporting.overtime_request WHERE workflow_state = ''Approved'' AND overtime_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_087', 'HR-087 Total Payroll Cost (Gross) (IDR)', 'Total gross salary paid across organization per period Target: Within budget. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(total_gross), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_088', 'HR-088 Total Employer Cost (IDR)', 'Total employee cost including gross salary and employer contributions Target: Within budget. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(total_gross + total_employer_contributions), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_089', 'HR-089 Average Gross Salary per Employee (IDR)', 'Average gross earnings per employee Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(SUM(total_gross) / NULLIF(SUM(employee_count), 0), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_090', 'HR-090 Net-to-Gross Ratio (%)', 'Take-home pay compared to gross salary Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(total_net_pay)) / NULLIF(SUM(total_gross), 0), 2) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_091', 'HR-091 Payroll Variance MoM (%)', 'Month-over-month percentage change in gross payroll Target: ± 3% (excluding holiday allowance/bonus). Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "WITH m AS (SELECT period, SUM(total_gross) AS g, MAX(posting_date) AS d FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date <= @End GROUP BY period), r AS (SELECT g, LAG(g) OVER (ORDER BY d) AS prev, ROW_NUMBER() OVER (ORDER BY d DESC) AS rn FROM m) SELECT (SELECT ROUND(100.0 * (g - prev) / NULLIF(prev, 0), 2) FROM r WHERE rn = 1) AS value", "parameters": [{"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_092', 'HR-092 Payroll On-time Rate (%)', 'Payroll disbursement completed on or before scheduled pay date Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.payment_entry pe JOIN reporting.payment_run pr ON pr.name = pe.payment_run WHERE pr.payroll_run = r.name AND pe.docstatus = 1 AND pe.posting_date <= r.payment_date))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payroll_run r WHERE r.docstatus = 1 AND r.payment_date BETWEEN @Start AND LEAST(@End, CURRENT_DATE)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_093', 'HR-093 Payroll Accuracy (%)', 'Percentage of payslips generated without corrections or amendments Target: ≥ 99,5%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100 - 100.0 * COUNT(*) FILTER (WHERE p.docstatus = 2) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus IN (1, 2) AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_094', 'HR-094 Active Employees Without Salary Assignment (Persons)', 'Active employees missing an active salary structure assignment Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employee e WHERE e.status = ''Active'' AND NOT EXISTS (SELECT 1 FROM reporting.salary_assignment s WHERE s.employee = e.name AND s.is_active)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_096', 'HR-096 Effective PPh 21 Rate (%)', 'Income tax withholding (PPh 21) compared to taxable gross pay Target: Per statutory withholding table (TER). Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(p.pph21)) / NULLIF(SUM(p.taxable_gross), 0), 2) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_097', 'HR-097 Government-borne Tax (PPh 21 DTP) Utilized (IDR)', 'Value of government-borne income tax incentives utilized Target: 100% eligible employees covered. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(total_pph21_dtp), 0) AS value FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_098', 'HR-098 December Tax Withholding Variance (IDR)', 'Annualized PPh 21 tax variance adjusted in December final payroll Target: Near 0. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(p.pph21_annual - p.pph21_before), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End AND p.is_last_period", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_099', 'HR-099 Employer Social Security (BPJS TK) Cost (IDR)', 'Employer social security contributions (JHT + JP + JKK + JKM) Target: Per PayrollSettings rate. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(p.jht_employer + p.jp_employer + p.jkk + p.jkm), 0), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_100', 'HR-100 Employer Health Insurance (BPJS Kes) Cost (IDR)', 'Employer healthcare insurance premium contributions Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(p.kes_employer), 0), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_101', 'HR-101 Social Security (BPJS) Participation (%)', 'Active employees enrolled in statutory BPJS TK and Health schemes Target: 100%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.salary_assignment s WHERE s.employee = e.name AND s.is_active AND s.bpjs_employment AND s.bpjs_health))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee e WHERE e.status = ''Active''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_102', 'HR-102 Non-regular Components % Gross (%)', 'Bonus, THR, and variable payments compared to gross payroll Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT SUM(x.amount) FROM reporting.payslip_earnings x JOIN reporting.payslip p ON p.name = x.parent JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End AND NOT COALESCE(x.is_regular, true)) / NULLIF((SELECT SUM(p.gross_earnings) FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_103', 'HR-103 Attendance Deductions (Days / IDR)', 'Salary deductions incurred from absences and unpaid leave Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(p.absent_days + p.unpaid_leave_days), 0) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_104', 'HR-104 Payroll Cost per Cost Center', 'Gross payroll and employer taxes distributed by cost center Target: Within budget. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(p.cost_center, ''(blank)'') AS label, SUM(p.gross_earnings + p.employer_contributions) AS value FROM reporting.payslip p JOIN reporting.payroll_run r ON r.name = p.payroll_run WHERE p.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_105', 'HR-105 Appraisal Completion Rate (%)', 'Performance appraisals completed within evaluation cycle Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active'') * (SELECT COUNT(*) FROM (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start) c), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_106', 'HR-106 Average Final Score (Score)', 'Average final performance evaluation appraisal score Target: —. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(final_score), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_107', 'HR-107 Rating Distribution', 'Percentage distribution of employees across performance rating tiers Target: Outstanding ≤ 10%, Unsatisfactory ≤ 5%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(rating, ''(unrated)'') AS label, COUNT(*) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start) GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "pie", "xColumn": "label", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_108', 'HR-108 High Performer Ratio (%)', 'Percentage of employees rated Outstanding or Exceeds Expectations Target: 15–25%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE rating IN (''Outstanding'',''Exceeds expectations''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_109', 'HR-109 Low Performer Ratio (%)', 'Percentage of employees rated Needs Improvement or Unsatisfactory Target: ≤ 10%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE rating IN (''Needs improvement'',''Unsatisfactory''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_110', 'HR-110 Goal Weight Compliance (%)', 'Percentage of appraisals where goal weights total exactly 100% Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE total_weight = 100)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state <> ''Cancelled'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_111', 'HR-111 Self vs Manager Score Gap (Points)', 'Average variance between employee self-score and manager rating Target: Near 0. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(g.self_score - g.manager_score), 2) AS value FROM reporting.appraisal_goals g JOIN reporting.appraisal a ON a.name = g.parent WHERE a.workflow_state = ''Completed'' AND a.appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start) AND g.self_score IS NOT NULL AND g.manager_score IS NOT NULL", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_112', 'HR-112 Development Plans Completed (%)', 'Performance appraisals with defined individual development plans Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(development_plan, '''') <> '''')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.appraisal WHERE workflow_state = ''Completed'' AND appraisal_cycle IN (SELECT name FROM reporting.appraisal_cycle WHERE start_date <= @End AND end_date >= @Start)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_113', 'HR-113 Appraisal Overdue (Appraisals)', 'Incomplete appraisals after evaluation cycle closing date Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.appraisal a JOIN reporting.appraisal_cycle c ON c.name = a.appraisal_cycle WHERE a.workflow_state NOT IN (''Completed'',''Cancelled'') AND c.end_date < CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_114', 'HR-114 Regretted Attrition High Performer (%)', 'High-performing employees resigning voluntarily Target: ≤ 5%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "WITH last_rating AS (SELECT DISTINCT ON (a.employee) a.employee, a.rating FROM reporting.appraisal a JOIN reporting.appraisal_cycle c ON c.name = a.appraisal_cycle WHERE a.workflow_state = ''Completed'' ORDER BY a.employee, c.end_date DESC), hp AS (SELECT employee FROM last_rating WHERE rating IN (''Outstanding'',''Exceeds expectations'')) SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.separation_type = ''Resignation'' AND s.last_working_date BETWEEN @Start AND @End AND s.employee IN (SELECT employee FROM hp)) / NULLIF((SELECT COUNT(*) FROM hp), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_115', 'HR-115 Training Hours per Employee (Hours)', 'Total employee training hours delivered compared to headcount Target: ≥ 20 hours/year. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND((SELECT SUM(EXTRACT(EPOCH FROM (t.end_at - t.start_at)) / 3600.0) FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE x.attendance = ''Attended'' AND t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 1) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_116', 'HR-116 Training Attendance Rate (%)', 'Actual training participants compared to registered attendees Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE x.attendance = ''Attended'')) / NULLIF(COUNT(*) FILTER (WHERE x.attendance IN (''Attended'',''Absent'')), 0), 2) AS value FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_117', 'HR-117 Training Cost per Participant (IDR)', 'Total training expense per actual attendee Target: Within L&D budget. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(SUM(t.cost) / NULLIF(SUM(t.attended_count), 0), 0) AS value FROM reporting.training_event t WHERE t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_118', 'HR-118 Training Spend % Payroll (%)', 'Training budget investment compared to gross payroll expense Target: 1–3%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT SUM(t.cost) FROM reporting.training_event t WHERE t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(total_gross) FROM reporting.payroll_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_119', 'HR-119 Average Training Score (Score)', 'Average participant test or evaluation score post-training Target: ≥ 75. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(x.score), 1) AS value FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE x.attendance = ''Attended'' AND x.score IS NOT NULL AND t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_120', 'HR-120 Training Coverage (%)', 'Percentage of active employees participating in at least 1 training event Target: ≥ 80%/year. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(DISTINCT x.employee) FROM reporting.training_event_attendees x JOIN reporting.training_event t ON t.name = x.parent WHERE x.attendance = ''Attended'' AND t.docstatus = 1 AND t.start_at::date BETWEEN @Start AND @End) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active''), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_122', 'HR-122 Turnover Rate (%)', 'Total employee separations compared to average headcount Target: ≤ 10%/year. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End) / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_123', 'HR-123 Voluntary Turnover Rate (%)', 'Voluntary resignations compared to average headcount Target: ≤ 7%/year. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.separation_type = ''Resignation'') / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_124', 'HR-124 Involuntary Turnover Rate (%)', 'Employer-initiated terminations compared to average headcount Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.separation_type = ''PHK'') / NULLIF((((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @Start::date AND (e.separation_date IS NULL OR e.separation_date > @Start::date)) + (SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date <= @End::date AND (e.separation_date IS NULL OR e.separation_date > @End::date))) / 2.0), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_125', 'HR-125 First-Year Attrition (%)', 'Employees leaving with less than 1 year of service Target: ≤ 15%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT COUNT(*) FROM reporting.employee_separation s JOIN reporting.employee e ON e.name = s.employee WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.last_working_date - e.hire_date < 365) / NULLIF((SELECT COUNT(*) FROM reporting.employee e WHERE e.hire_date BETWEEN @Start::date - 365 AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_126', 'HR-126 Retention Rate (%)', 'Employees retained from beginning to end of period Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE separation_date IS NULL OR separation_date > @End)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee WHERE hire_date < @Start AND (separation_date IS NULL OR separation_date >= @Start)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_127', 'HR-127 Exit Interview Completion (%)', 'Separations with completed exit interview documentation Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE s.exit_interview_done)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_128', 'HR-128 Eligible for Rehire Ratio (%)', 'Departing employees designated as eligible for rehire Target: —. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE s.eligible_for_rehire)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_129', 'HR-129 Clearance Checklist Completion (%)', 'Offboarding asset and access clearance items completed Target: 100% before last working date. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE c.is_done)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.employee_separation_checklist c JOIN reporting.employee_separation s ON s.name = c.parent WHERE s.docstatus IN (0, 1) AND s.last_working_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_130', 'HR-130 Average Notice Period (Days)', 'Average days between notice date and last working date Target: ≥ 30 days (resignation). Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(s.last_working_date - s.notice_date), 1) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End AND s.notice_date IS NOT NULL", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_132', 'HR-132 Departed Employees With Active Access (Persons)', 'Employees with Left status retaining active salary structure or system access Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employee e WHERE e.status = ''Left'' AND EXISTS (SELECT 1 FROM reporting.salary_assignment s WHERE s.employee = e.name AND s.is_active)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_hr_133', 'HR-133 Exit Reason Breakdown', 'Percentage distribution of departures by separation reason Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(s.separation_type, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.employee_separation s WHERE s.docstatus = 1 AND s.last_working_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "pie", "xColumn": "label", "yColumns": ["value"]}, "roles": ["HR"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_001', 'FIN-001 Total Outstanding Receivables (IDR)', 'Outstanding balance of unpaid sales invoices Target: —. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND((SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.sales_invoice WHERE docstatus = 1) - (SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.sales_credit_note WHERE docstatus = 1), 0) AS value", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_002', 'FIN-002 DSO (Days Sales Outstanding) (Days)', 'Average collection period for receivables in days Target: ≤ 45 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND((SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.sales_invoice WHERE docstatus = 1) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0) * (@End::date - @Start::date + 1), 1) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_003', 'FIN-003 Overdue Receivables (IDR)', 'Receivables past due date Target: ≤ 10% total AR. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(outstanding_amount * exchange_rate), 0), 0) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0 AND due_date < CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_004', 'FIN-004 Overdue AR % (%)', 'Proportion of receivables past due Target: ≤ 10%. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(outstanding_amount * exchange_rate) FILTER (WHERE due_date < CURRENT_DATE)) / NULLIF(SUM(outstanding_amount * exchange_rate), 0), 2) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_005', 'FIN-005 AR Aging > 90 Days (%)', 'Receivables overdue by more than 90 days Target: ≤ 5%. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(outstanding_amount * exchange_rate) FILTER (WHERE CURRENT_DATE - due_date > 90)) / NULLIF(SUM(outstanding_amount * exchange_rate), 0), 2) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_007', 'FIN-007 Average Days to Pay (Days)', 'Average days elapsed from invoice date to customer payment Target: ≤ payment terms. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(pe.posting_date - si.posting_date), 1) AS value FROM reporting.payment_entry_references r JOIN reporting.payment_entry pe ON pe.name = r.parent JOIN reporting.sales_invoice si ON si.name = r.reference_name WHERE r.reference_doctype = ''SalesInvoice'' AND pe.docstatus = 1 AND pe.payment_type = ''Receive'' AND pe.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_008', 'FIN-008 Customers Over Credit Limit (Customers)', 'Number of customers with outstanding balances exceeding credit limit Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) FILTER (WHERE ar > credit_limit) AS value FROM (SELECT c.name, c.credit_limit, COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.customer = c.name AND si.docstatus = 1), 0) AS ar FROM reporting.customer c WHERE c.is_active AND COALESCE(c.credit_limit, 0) > 0) x", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_009', 'FIN-009 Credit Limit Utilization (%)', 'Overall customer credit limit exposure Target: ≤ 80%. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(ar)) / NULLIF(SUM(credit_limit), 0), 2) AS value FROM (SELECT c.name, c.credit_limit, COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.customer = c.name AND si.docstatus = 1), 0) AS ar FROM reporting.customer c WHERE c.is_active AND COALESCE(c.credit_limit, 0) > 0) x", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_010', 'FIN-010 Credit Note Ratio (%)', 'Sales credit notes issued compared to gross revenue Target: ≤ 2%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT SUM(base_grand_total) FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_011', 'FIN-011 Credit Notes by Reason', 'Breakdown of credit notes by reason (returns, discounts, price adjustments, cancellations) Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(reason, ''(blank)'') AS label, SUM(base_grand_total) AS value FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "pie", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_012', 'FIN-012 Unapplied Customer Payments (IDR)', 'Customer receipts not yet allocated to specific invoices Target: Near 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(unallocated_amount * exchange_rate), 0), 0) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND payment_type = ''Receive'' AND unallocated_amount > 0", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_013', 'FIN-013 Payment Reconciliation Backlog (Documents)', 'Number of unapplied payment entries pending reconciliation Target: 0 at month end. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND payment_type IN (''Receive'',''Pay'') AND unallocated_amount > 0", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_014', 'FIN-014 Invoices Without Tax Invoice (Invoices)', 'Taxable sales invoices missing official tax invoice numbers Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND vat_amount > 0 AND COALESCE(tax_invoice_no, '''') = '''' AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_015', 'FIN-015 Net Sales (IDR)', 'Total sales revenue net of credit notes Target: Per target. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE((SELECT SUM(total * exchange_rate) FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0) - COALESCE((SELECT SUM(total * exchange_rate) FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 0) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_016', 'FIN-016 Top 10 AR Concentration (%)', 'Share of outstanding receivables held by the top 10 customers Target: ≤ 50%. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "WITH c AS (SELECT customer, SUM(outstanding_amount * exchange_rate) AS ar FROM reporting.sales_invoice WHERE docstatus = 1 AND outstanding_amount > 0 GROUP BY customer) SELECT ROUND(100.0 * (SELECT SUM(ar) FROM (SELECT ar FROM c ORDER BY ar DESC LIMIT 10) t) / NULLIF((SELECT SUM(ar) FROM c), 0), 2) AS value", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_018', 'FIN-018 Invoices With Milestone Terms (%)', 'Percentage of invoices utilizing payment schedules Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE (SELECT COUNT(*) FROM reporting.sales_invoice_payment_schedule s WHERE s.parent = si.name) >= 2)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_019', 'FIN-019 Total Outstanding Payables (IDR)', 'Outstanding balance of unpaid purchase invoices Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT (SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.purchase_invoice WHERE docstatus = 1) - (SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.purchase_debit_note WHERE docstatus = 1) AS value", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_020', 'FIN-020 DPO (Days Payable Outstanding) (Days)', 'Average time taken to pay vendor bills in days Target: Per payment term (e.g. 30–60). Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND((SELECT COALESCE(SUM(outstanding_amount * exchange_rate), 0) FROM reporting.purchase_invoice WHERE docstatus = 1) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0) * (@End::date - @Start::date + 1), 1) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_021', 'FIN-021 On-time Payment Rate (%)', 'Vendor payments executed on or before invoice due date Target: ≥ 95%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE pe.posting_date <= COALESCE(r.due_date, pi.due_date))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payment_entry_references r JOIN reporting.payment_entry pe ON pe.name = r.parent JOIN reporting.purchase_invoice pi ON pi.name = r.reference_name WHERE r.reference_doctype = ''PurchaseInvoice'' AND pe.docstatus = 1 AND pe.payment_type = ''Pay'' AND pe.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_022', 'FIN-022 Late Payment Amount (IDR)', 'Total monetary value of overdue vendor payables not on hold Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(outstanding_amount * exchange_rate), 0), 0) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND outstanding_amount > 0 AND due_date < CURRENT_DATE AND NOT COALESCE(on_hold, false)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_023', 'FIN-023 Invoices On Hold (Invoices / IDR)', 'Vendor invoices with payment withheld on hold Target: —. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(outstanding_amount * exchange_rate), 0), 0) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND outstanding_amount > 0 AND on_hold", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_024', 'FIN-024 Invoice Processing Time (Days)', 'Days from vendor bill date to invoice submission in system Target: ≤ 3 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(posting_date - bill_date), 1) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND bill_date IS NOT NULL AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_025', 'FIN-025 PO-backed Invoice Rate (%)', 'Purchase invoices originating from purchase orders Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE purchase_order IS NOT NULL)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_027', 'FIN-027 Duplicate Bill Numbers (Cases)', 'Vendor invoices sharing duplicate external bill numbers Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM (SELECT vendor, bill_no FROM reporting.purchase_invoice WHERE docstatus = 1 AND COALESCE(bill_no, '''') <> '''' GROUP BY 1, 2 HAVING COUNT(*) > 1) d", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_028', 'FIN-028 Debit Note Ratio (%)', 'Purchase debit notes issued compared to gross purchases Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SELECT SUM(base_grand_total) FROM reporting.purchase_debit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(base_grand_total) FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_029', 'FIN-029 Unapplied Vendor Payments (IDR)', 'Disbursements to vendors not yet allocated to invoices Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(unallocated_amount * exchange_rate), 0), 0) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND payment_type = ''Pay'' AND unallocated_amount > 0", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_034', 'FIN-034 Net Cash Flow (IDR)', 'Cash receipts minus cash disbursements across all payment entries Target: Positive. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(base_paid_amount) FILTER (WHERE payment_type = ''Receive''), 0) - COALESCE(SUM(base_paid_amount) FILTER (WHERE payment_type = ''Pay''), 0) AS value FROM reporting.payment_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_035', 'FIN-035 Bank Reconciliation Timeliness (%)', 'Bank reconciliations completed within 3 working days post month-end Target: 100%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.bank_reconciliation r WHERE r.bank_account = b.name AND r.docstatus = 1 AND r.period_end = (date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date AND r.created::date <= (date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date + 5))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.bank_account b WHERE b.is_active", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_036', 'FIN-036 Bank Reconciliation Difference (IDR)', 'Total unexplained bank reconciliation variance Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(ABS(difference)), 0) AS value FROM reporting.bank_reconciliation WHERE docstatus = 1 AND period_end BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_037', 'FIN-037 Uncleared Items (IDR / item)', 'Book transactions not yet cleared on bank statements Target: —. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(i.uncleared_amount), 0) AS value FROM reporting.bank_reconciliation_items i JOIN reporting.bank_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND NOT COALESCE(i.is_cleared, false) AND r.period_end = (SELECT MAX(period_end) FROM reporting.bank_reconciliation WHERE docstatus = 1)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_038', 'FIN-038 Aged Uncleared Items > 30 Days (Items)', 'Uncleared bank reconciliation items outstanding > 30 days Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.bank_reconciliation_items i JOIN reporting.bank_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND NOT COALESCE(i.is_cleared, false) AND r.period_end - i.posting_date > 30 AND r.period_end = (SELECT MAX(period_end) FROM reporting.bank_reconciliation WHERE docstatus = 1)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_039', 'FIN-039 Bank Statement Auto-match Rate (%)', 'Bank statement lines matched automatically by reconciliation rules Target: ≥ 85%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE l.match_status = ''Matched'')) / NULLIF(COUNT(*) FILTER (WHERE l.match_status <> ''Ignored''), 0), 2) AS value FROM reporting.bank_statement_lines l JOIN reporting.bank_statement s ON s.name = l.parent WHERE s.docstatus IN (0, 1) AND l.transaction_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_040', 'FIN-040 Unmatched Bank Lines (Lines)', 'Bank statement transaction lines pending manual reconciliation Target: 0 at close. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.bank_statement_lines l JOIN reporting.bank_statement s ON s.name = l.parent WHERE s.docstatus IN (0, 1) AND l.match_status = ''Unmatched''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_041', 'FIN-041 Statement Balance Integrity Check (Statements)', 'Bank statements where calculated closing does not match stated closing Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.bank_statement WHERE docstatus IN (0, 1) AND ABS(COALESCE(computed_closing, 0) - COALESCE(closing_balance, 0)) > 0.005", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_042', 'FIN-042 Payment Run Efficiency (Payments)', 'Number of payment entries processed per batch payment run Target: —. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(payments_created), 1) AS value FROM reporting.payment_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_044', 'FIN-044 Vendors Without Bank Account (Vendors)', 'Active suppliers lacking electronic banking payment details Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.vendor v WHERE v.is_active AND NOT EXISTS (SELECT 1 FROM reporting.vendor_bank_accounts b WHERE b.parent = v.name)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_045', 'FIN-045 FX Exposure (IDR)', 'Total outstanding foreign currency receivable and payable exposure Target: Per hedging policy. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si JOIN reporting.company c ON c.name = si.company WHERE si.docstatus = 1 AND si.currency <> c.base_currency), 0) + COALESCE((SELECT SUM(pi.outstanding_amount * pi.exchange_rate) FROM reporting.purchase_invoice pi JOIN reporting.company c ON c.name = pi.company WHERE pi.docstatus = 1 AND pi.currency <> c.base_currency), 0), 0) AS value", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_046', 'FIN-046 Missing Daily Exchange Rates (Pairs)', 'Active currency pairs missing foreign exchange rate for today Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.currency cur WHERE cur.is_active AND cur.name NOT IN (SELECT base_currency FROM reporting.company WHERE base_currency IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM reporting.currency_exchange_rate r WHERE r.from_currency = cur.name AND r.rate_date = CURRENT_DATE)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_047', 'FIN-047 Total Expense Claims (IDR)', 'Total employee business expense reimbursements claimed Target: Within budget. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(c.total_claimed), 0) AS value FROM reporting.expense_claim c WHERE c.workflow_state = ''Approved'' AND c.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_048', 'FIN-048 Expense Claim per Employee (IDR)', 'Average business reimbursement expense claimed per employee Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND((SELECT SUM(c.total_claimed) FROM reporting.expense_claim c WHERE c.workflow_state = ''Approved'' AND c.posting_date BETWEEN @Start AND @End) / NULLIF((SELECT COUNT(*) FROM reporting.employee WHERE status = ''Active''), 0), 0) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_049', 'FIN-049 Expense Claim Cycle Time (Days)', 'Average days from claim submission date to payment disbursement Target: ≤ 7 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(pe.posting_date - c.posting_date), 1) AS value FROM reporting.payment_entry_references r JOIN reporting.payment_entry pe ON pe.name = r.parent JOIN reporting.expense_claim c ON c.name = r.reference_name WHERE r.reference_doctype = ''ExpenseClaim'' AND pe.docstatus = 1 AND pe.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_051', 'FIN-051 Expense Rejection Rate (%)', 'Percentage of employee expense claims rejected Target: ≤ 5%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Rejected'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Approved'',''Rejected'')), 0), 2) AS value FROM reporting.expense_claim WHERE posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_053', 'FIN-053 Policy Breach (Over Limit) (Items)', 'Claim items submitted exceeding maximum policy allowance Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.expense_claim_items i JOIN reporting.expense_claim c ON c.name = i.parent JOIN reporting.expense_claim_type t ON t.name = i.expense_type WHERE c.workflow_state NOT IN (''Draft'',''Cancelled'') AND COALESCE(t.max_amount_per_item, 0) > 0 AND i.amount > t.max_amount_per_item AND c.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_054', 'FIN-054 Entertainment Expense Spend (IDR)', 'Total entertainment claims incurred requiring fiscal nominative reporting Target: Within budget. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(i.amount), 0) AS value FROM reporting.expense_claim_items i JOIN reporting.expense_claim c ON c.name = i.parent JOIN reporting.expense_claim_type t ON t.name = i.expense_type WHERE c.workflow_state = ''Approved'' AND t.is_entertainment AND c.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_055', 'FIN-055 Expenses by Project', 'Employee reimbursement costs allocated to specific projects Target: Per project estimate. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(c.project, ''(no project)'') AS label, SUM(c.total_claimed) AS value FROM reporting.expense_claim c WHERE c.workflow_state = ''Approved'' AND c.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_056', 'FIN-056 Outstanding Employee Advances (IDR)', 'Total employee advances outstanding pending settlement Target: —. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(COALESCE(paid_amount, 0) - COALESCE(settled_amount, 0) - COALESCE(returned_amount, 0)), 0) AS value FROM reporting.employee_advance WHERE docstatus = 1 AND advance_status <> ''Completed''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_057', 'FIN-057 Overdue Advance Settlements (Advances)', 'Employee advances past settlement due date not yet resolved Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.employee_advance WHERE docstatus = 1 AND advance_status IN (''Paid'',''Partly Settled'') AND settle_by_date < CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_058', 'FIN-058 Advance Settlement Ratio (%)', 'Proportion of employee advances settled via expense claims Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(COALESCE(settled_amount, 0) + COALESCE(returned_amount, 0))) / NULLIF(SUM(paid_amount), 0), 2) AS value FROM reporting.employee_advance WHERE docstatus = 1 AND paid_amount > 0 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_059', 'FIN-059 Unpaid Approved Claims (IDR)', 'Approved expense reimbursements awaiting payment disbursement Target: 0 > 7 days. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(net_payable), 0) AS value FROM reporting.expense_claim WHERE workflow_state = ''Approved'' AND payment_status IN (''Unpaid'',''Partly Paid'')", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_060', 'FIN-060 Output VAT (PPN Keluaran) (IDR)', 'Total output value-added tax collected on sales Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(vat_amount), 0) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND status NOT IN (''Cancelled'',''Replaced'') AND tax_invoice_date BETWEEN @Start AND @End AND direction = ''Output''", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_061', 'FIN-061 Input VAT (PPN Masukan) (IDR)', 'Total creditable input value-added tax paid on purchases Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(vat_amount), 0) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND status NOT IN (''Cancelled'',''Replaced'') AND tax_invoice_date BETWEEN @Start AND @End AND direction = ''Input''", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_062', 'FIN-062 VAT Payable / Overpaid (IDR)', 'Net VAT balance payable to tax authority or refundable Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(vat_amount) FILTER (WHERE direction = ''Output''), 0) - COALESCE(SUM(vat_amount) FILTER (WHERE direction = ''Input''), 0) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND status NOT IN (''Cancelled'',''Replaced'') AND tax_invoice_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_063', 'FIN-063 Tax Invoice Approval Rate (%)', 'Tax invoices officially validated and approved by tax authority (DJP) Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Approved'')) / NULLIF(COUNT(*) FILTER (WHERE status <> ''Cancelled''), 0), 2) AS value FROM reporting.tax_invoice WHERE docstatus IN (0, 1) AND direction = ''Output'' AND tax_invoice_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_064', 'FIN-064 Tax Invoices Pending Upload (Tax invoices)', 'Draft tax invoices pending submission or export to e-Faktur Target: 0 before filing deadline. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.tax_invoice WHERE docstatus IN (0, 1) AND direction = ''Output'' AND status = ''Draft''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_065', 'FIN-065 Replacement Tax Invoice Rate (%)', 'Percentage of tax invoices requiring replacement (e-Faktur pengganti) Target: ≤ 1%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE replaces IS NOT NULL)) / NULLIF(COUNT(*) FILTER (WHERE status <> ''Cancelled''), 0), 2) AS value FROM reporting.tax_invoice WHERE docstatus IN (0, 1) AND direction = ''Output'' AND tax_invoice_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_066', 'FIN-066 Uncredited Input Tax Invoices (Tax invoices)', 'Input tax invoices not yet claimed in a VAT tax return period Target: 0 within 3 months. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.tax_invoice WHERE docstatus = 1 AND direction = ''Input'' AND status NOT IN (''Cancelled'',''Replaced'') AND COALESCE(credited_period, '''') = ''''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_067', 'FIN-067 Withholding Tax (PPh 23) Payable (IDR)', 'Total income tax withheld from vendor payments (PPh 23/4(2)) Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(wht_amount * exchange_rate), 0), 0) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_068', 'FIN-068 Withholding Certificates Issued (%)', 'Purchase invoices with tax withholding where tax certificate was issued Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.withholding_certificate w WHERE w.direction = ''We withhold'' AND w.reference_doctype = ''PurchaseInvoice'' AND w.reference_name = pi.name AND w.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.purchase_invoice pi WHERE pi.docstatus = 1 AND pi.wht_amount > 0 AND pi.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_069', 'FIN-069 Customer Withholding Certificates Received (%)', 'Deductions withheld by customers with verified certificates collected Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.withholding_certificate w WHERE w.direction = ''Withheld by counterparty'' AND w.party = pe.party AND w.docstatus = 1 AND w.reference_name IN (SELECT r.reference_name FROM reporting.payment_entry_references r WHERE r.parent = pe.name)))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payment_entry pe WHERE pe.docstatus = 1 AND pe.payment_type = ''Receive'' AND pe.posting_date BETWEEN @Start AND @End AND EXISTS (SELECT 1 FROM reporting.payment_entry_deductions d WHERE d.parent = pe.name AND d.deduction_type = ''Tax withheld by counterparty'')", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_071', 'FIN-071 Taxable Counterparties Without Tax ID (Records)', 'Taxable vendor or customer master records missing valid tax ID (NPWP) Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT (SELECT COUNT(*) FROM reporting.customer WHERE is_active AND is_pkp AND COALESCE(tax_id, '''') = '''') + (SELECT COUNT(*) FROM reporting.vendor WHERE is_active AND is_pkp AND COALESCE(tax_id, '''') = '''') AS value", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_072', 'FIN-072 Fixed Assets Net Book Value (IDR)', 'Gross asset acquisition cost minus cumulative depreciation Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(a.gross_purchase_amount - COALESCE(a.opening_accumulated_depreciation, 0) - COALESCE((SELECT SUM(s.depreciation_amount) FROM reporting.asset_schedule s WHERE s.parent = a.name AND s.is_posted), 0)), 0) AS value FROM reporting.asset a WHERE a.docstatus = 1 AND a.status IN (''Active'',''Fully Depreciated'')", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_073', 'FIN-073 Period Depreciation Expense (IDR)', 'Total depreciation posted to general ledger for the period Target: On schedule. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(total_depreciation), 0) AS value FROM reporting.depreciation_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_074', 'FIN-074 Depreciation Run Completion (%)', 'Percentage of accounting periods with completed monthly depreciation runs Target: 100% before close. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.depreciation_run d WHERE d.accounting_period = p.name AND d.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.accounting_period p WHERE p.end_date BETWEEN @Start AND LEAST(@End, CURRENT_DATE)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_075', 'FIN-075 Unposted Depreciation Schedules (Lines)', 'Asset depreciation schedule rows past due date not yet posted Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.asset_schedule s JOIN reporting.asset a ON a.name = s.parent WHERE a.docstatus = 1 AND a.status = ''Active'' AND s.schedule_date <= CURRENT_DATE AND NOT COALESCE(s.is_posted, false)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_076', 'FIN-076 Average Asset Depreciated % (%)', 'Cumulative depreciation compared to gross acquisition cost Target: < 70% (assets not obsolete). Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * SUM(COALESCE(a.opening_accumulated_depreciation, 0) + COALESCE((SELECT SUM(s.depreciation_amount) FROM reporting.asset_schedule s WHERE s.parent = a.name AND s.is_posted), 0)) / NULLIF(SUM(a.gross_purchase_amount), 0), 2) AS value FROM reporting.asset a WHERE a.docstatus = 1 AND a.status IN (''Active'',''Fully Depreciated'')", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_077', 'FIN-077 Fully Depreciated Assets In Use (Assets)', 'Assets completely written off but still actively in service Target: Evaluated for replacement. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 1 AND status = ''Fully Depreciated''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_078', 'FIN-078 Disposal Gain / Loss (IDR)', 'Net gain or loss realized on fixed asset retirements and disposals Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(gain_loss), 0) AS value FROM reporting.asset_disposal WHERE docstatus = 1 AND disposal_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_079', 'FIN-079 Write-offs & Lost Assets (IDR)', 'Net book value of assets scrapped, lost, or written off Target: Minimal. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(book_value), 0) AS value FROM reporting.asset_disposal WHERE docstatus = 1 AND disposal_type IN (''Write-off'',''Lost/Damaged'') AND disposal_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_080', 'FIN-080 Assets Without Custodian (Assets)', 'Active fixed assets missing an assigned custodian or owner Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 1 AND status = ''Active'' AND custodian IS NULL", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_081', 'FIN-081 Assets Without Location / Cost Center (Assets)', 'Active fixed assets lacking an assigned physical location or cost center Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 1 AND status = ''Active'' AND (location IS NULL OR cost_center IS NULL)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_082', 'FIN-082 Period Capex (IDR)', 'Total capital expenditures invested in new fixed assets during period Target: Within capex budget. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(gross_purchase_amount), 0) AS value FROM reporting.asset WHERE docstatus = 1 AND NOT COALESCE(is_existing_asset, false) AND purchase_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_083', 'FIN-083 Draft Assets Not Activated (Assets)', 'Capital assets purchased over 30 days ago remaining in Draft state Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.asset WHERE docstatus = 0 AND purchase_date < CURRENT_DATE - 30", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_fin_084', 'FIN-084 Capex to Depreciation Ratio (Ratio)', 'Capital expenditure investment compared to periodic depreciation charge Target: ≥ 1 (business growing). Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND((SELECT SUM(gross_purchase_amount) FROM reporting.asset WHERE docstatus = 1 AND NOT COALESCE(is_existing_asset, false) AND purchase_date BETWEEN @Start AND @End) / NULLIF((SELECT SUM(total_depreciation) FROM reporting.depreciation_run WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_001', 'ACC-001 Manual Journal Count (Journals)', 'Number of manual journal entries posted per period Target: Decrease with automation. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_002', 'ACC-002 Manual Journal Ratio (%)', 'Manual journals compared to total general ledger transactions Target: ≤ 10%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "WITH v AS (SELECT ''JE'' AS t FROM reporting.journal_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.payment_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.sales_credit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.purchase_debit_note WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End UNION ALL SELECT ''X'' FROM reporting.stock_entry WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End) SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE t = ''JE'') / NULLIF(COUNT(*), 0), 2) AS value FROM v", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_004', 'ACC-004 Rejected Unbalanced Journals (Journals)', 'Journal entries created with debit/credit difference not equal to zero Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry WHERE docstatus = 0 AND ABS(COALESCE(difference, 0)) > 0.005", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_005', 'ACC-005 Auto-reversal Compliance (%)', 'Accrual journals marked for auto-reversal that have been reversed Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.journal_entry r WHERE r.reversal_of = j.name AND r.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.journal_entry j WHERE j.docstatus = 1 AND j.auto_reverse AND j.reversal_date <= CURRENT_DATE AND j.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_006', 'ACC-006 Cancelled / Amended Journals (%)', 'Percentage of journal entries cancelled or amended post-submission Target: ≤ 2%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE docstatus = 2)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.journal_entry WHERE docstatus IN (1, 2) AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_007', 'ACC-007 Backdated Postings (Vouchers)', 'Transactions posted with effective dates preceding system entry by threshold Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM (SELECT posting_date, created FROM reporting.journal_entry WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.sales_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.purchase_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.payment_entry WHERE docstatus = 1) v WHERE v.created::date BETWEEN @Start AND @End AND v.created::date - v.posting_date > COALESCE((SELECT MAX(backdate_limit_days) FROM reporting.accounting_settings), 7)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_008', 'ACC-008 Future-dated Postings (Vouchers)', 'Transactions entered with posting dates set in future periods Target: 0 (unless authorized). Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM (SELECT posting_date, created FROM reporting.journal_entry WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.sales_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.purchase_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.payment_entry WHERE docstatus = 1) v WHERE v.created::date BETWEEN @Start AND @End AND v.posting_date > v.created::date", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_009', 'ACC-009 P&L Lines Without Cost Center (Lines)', 'Profit and loss journal entry lines missing an assigned cost center Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry_accounts l JOIN reporting.journal_entry j ON j.name = l.parent JOIN reporting.account a ON a.name = l.account WHERE j.docstatus = 1 AND j.posting_date BETWEEN @Start AND @End AND a.report_type = ''Profit and Loss'' AND l.cost_center IS NULL", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_010', 'ACC-010 Direct Postings to Control Accounts (Lines)', 'Manual journal lines posting directly to AR/AP control accounts without subledger party Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry_accounts l JOIN reporting.journal_entry j ON j.name = l.parent JOIN reporting.account a ON a.name = l.account WHERE j.docstatus = 1 AND j.posting_date BETWEEN @Start AND @End AND a.is_control_account AND l.party IS NULL", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_011', 'ACC-011 Postings to Frozen / Inactive Accounts (Occurrences)', 'Attempted postings to frozen accounts or deactivated accounts Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.journal_entry_accounts l JOIN reporting.journal_entry j ON j.name = l.parent JOIN reporting.account a ON a.name = l.account WHERE j.docstatus = 1 AND j.posting_date BETWEEN @Start AND @End AND (a.is_frozen OR NOT a.is_active)", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_016', 'ACC-016 Days to Close (Working days)', 'Working days from fiscal month end to official accounting period closure Target: ≤ 5 working days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(closed_on::date - end_date), 1) AS value FROM reporting.accounting_period WHERE status = ''Closed'' AND closed_on IS NOT NULL AND end_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_017', 'ACC-017 Overdue Open Fiscal Periods (Periods)', 'Fiscal periods remaining open more than 10 days past end date Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.accounting_period WHERE status = ''Open'' AND end_date < CURRENT_DATE - 10", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_018', 'ACC-018 Sub-ledger Lock Compliance (%)', 'Closed periods where AR, AP, Fixed Asset, and Payroll subledgers are locked Target: 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE lock_receivable AND lock_payable AND lock_fixed_asset AND lock_payroll)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.accounting_period WHERE status = ''Closed'' AND end_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_019', 'ACC-019 Post-close Adjustments (Vouchers)', 'Transactions posted into previously closed fiscal periods via reopen Target: 0. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM (SELECT posting_date, created FROM reporting.journal_entry WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.sales_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.purchase_invoice WHERE docstatus = 1 UNION ALL SELECT posting_date, created FROM reporting.payment_entry WHERE docstatus = 1) v JOIN reporting.accounting_period p ON v.posting_date BETWEEN p.start_date AND p.end_date WHERE p.status = ''Closed'' AND p.closed_on IS NOT NULL AND v.created > p.closed_on AND p.end_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_020', 'ACC-020 Books Frozen Lag (Days)', 'Days elapsed between prior month end and current books_frozen_until cutoff Target: ≤ 10 days. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ((date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date - MAX(books_frozen_until)) AS value FROM reporting.accounting_settings", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_021', 'ACC-021 Year-end Closing Completed (Yes/No)', 'Fiscal years closed with submitted Period Closing Vouchers Target: Completed ≤ 60 days post year-end. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.fiscal_year f WHERE f.end_date < CURRENT_DATE AND NOT EXISTS (SELECT 1 FROM reporting.period_closing_voucher v WHERE v.fiscal_year = f.name AND v.docstatus = 1)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_022', 'ACC-022 Intercompany Balance Mismatch (IDR)', 'Reconciliation imbalance between internal customer AR and internal vendor AP Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE((SELECT SUM(si.outstanding_amount * si.exchange_rate) FROM reporting.sales_invoice si JOIN reporting.customer c ON c.name = si.customer WHERE si.docstatus = 1 AND c.is_internal_customer), 0) - COALESCE((SELECT SUM(pi.outstanding_amount * pi.exchange_rate) FROM reporting.purchase_invoice pi JOIN reporting.vendor v ON v.name = pi.vendor WHERE pi.docstatus = 1 AND v.is_internal_vendor), 0) AS value", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_023', 'ACC-023 Exchange Rate Coverage at Close (%)', 'Active foreign currencies with verified period-end revaluation rates Target: 100%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.currency_exchange_rate r WHERE r.from_currency = cur.name AND r.rate_date = (date_trunc(''month'', CURRENT_DATE) - interval ''1 day'')::date))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.currency cur WHERE cur.is_active AND cur.name NOT IN (SELECT base_currency FROM reporting.company WHERE base_currency IS NOT NULL)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_042', 'ACC-042 Cost Centers Without Budget (Cost centers)', 'Active operational cost centers lacking an active annual budget allocation Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.cost_center cc WHERE cc.is_active AND NOT cc.is_group AND NOT EXISTS (SELECT 1 FROM reporting.budget b JOIN reporting.fiscal_year f ON f.name = b.fiscal_year WHERE b.cost_center = cc.name AND b.docstatus = 1 AND CURRENT_DATE BETWEEN f.start_date AND f.end_date)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_046', 'ACC-046 Project Billing Progress (%)', 'Invoices billed to date compared to total contracted project value Target: Per project progress. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(COALESCE((SELECT SUM(si.total * si.exchange_rate) FROM reporting.sales_invoice si WHERE si.project = p.name AND si.docstatus = 1), 0))) / NULLIF(SUM(p.contract_value), 0), 2) AS value FROM reporting.project p WHERE p.status IN (''In Progress'',''Completed'') AND p.contract_value > 0", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_047', 'ACC-047 Over-schedule Projects (Projects)', 'In-progress customer projects where scheduled end date has passed Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.project WHERE status = ''In Progress'' AND end_date < CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_acc_048', 'ACC-048 On-hold Projects (Projects)', 'Projects currently suspended in On Hold status Target: —. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.project WHERE status = ''On Hold''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_002', 'PRC-002 PR to PO Cycle Time (Days)', 'Days from purchase request approval to purchase order issuance Target: ≤ 5 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(po.order_date - pr.created::date), 1) AS value FROM reporting.purchase_order po JOIN reporting.purchase_request pr ON pr.name = po.purchase_request WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_003', 'PRC-003 PR Conversion Rate (%)', 'Percentage of approved purchase requests converted into purchase orders Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE order_status = ''Ordered'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.purchase_request WHERE workflow_state = ''Approved'' AND created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_004', 'PRC-004 PR Rejection Rate (%)', 'Percentage of submitted purchase requests rejected during workflow Target: ≤ 10%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE workflow_state = ''Rejected'')) / NULLIF(COUNT(*) FILTER (WHERE workflow_state IN (''Approved'',''Rejected'')), 0), 2) AS value FROM reporting.purchase_request WHERE created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_005', 'PRC-005 Overdue Purchase Requests (PRs)', 'Unordered purchase requests where the required-by date has passed Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.purchase_request WHERE workflow_state = ''Approved'' AND order_status <> ''Ordered'' AND required_by < CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_006', 'PRC-006 Total Spend (PO) (IDR)', 'Total monetary value of purchase orders issued and submitted Target: Within budget. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(total), 0), 0) AS value FROM reporting.purchase_order WHERE docstatus = 1 AND order_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_007', 'PRC-007 Spend Under Management (%)', 'Proportion of total procurement spend routed through formal purchase orders Target: ≥ 85%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(base_grand_total) FILTER (WHERE purchase_order IS NOT NULL)) / NULLIF(SUM(base_grand_total), 0), 2) AS value FROM reporting.purchase_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_008', 'PRC-008 Price Variance PR vs PO (%)', 'Percentage price variance between estimated PR cost and negotiated PO price Target: ≤ 0% (favorable/savings). Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(po.total) - SUM(pr.total_estimate)) / NULLIF(SUM(pr.total_estimate), 0), 2) AS value FROM reporting.purchase_order po JOIN reporting.purchase_request pr ON pr.name = po.purchase_request WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_009', 'PRC-009 Procurement Cost Savings (IDR)', 'Direct monetary savings achieved through supplier negotiation below estimates Target: ≥ 3% spend. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(GREATEST(pr.total_estimate - po.total, 0)), 0), 0) AS value FROM reporting.purchase_order po JOIN reporting.purchase_request pr ON pr.name = po.purchase_request WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_010', 'PRC-010 Open PO Value (IDR)', 'Monetary value of committed purchase orders awaiting receipt Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(grand_total - COALESCE(received_amount, 0)), 0), 0) AS value FROM reporting.purchase_order WHERE docstatus = 1 AND receipt_status <> ''Fully received''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_011', 'PRC-011 Unbilled Receipts (GRNI) (IDR)', 'Goods and services received from suppliers awaiting invoice billing Target: —. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(COALESCE(SUM(GREATEST(COALESCE(received_amount, 0) - COALESCE(billed_amount, 0), 0)), 0), 0) AS value FROM reporting.purchase_order WHERE docstatus = 1", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_012', 'PRC-012 Top 10 Vendor Spend Concentration (%)', 'Share of total procurement spend concentrated among the top 10 suppliers Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "WITH v AS (SELECT vendor, SUM(total) AS s FROM reporting.purchase_order WHERE docstatus = 1 AND order_date BETWEEN @Start AND @End GROUP BY vendor) SELECT ROUND(100.0 * (SELECT SUM(s) FROM (SELECT s FROM v ORDER BY s DESC LIMIT 10) t) / NULLIF((SELECT SUM(s) FROM v), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_013', 'PRC-013 Spend by Item Group', 'Distribution of purchasing spend across item groups and categories Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(it.item_group, ''(no group)'') AS label, SUM(i.amount) AS value FROM reporting.purchase_order_items i JOIN reporting.purchase_order po ON po.name = i.parent LEFT JOIN reporting.item it ON it.name = i.item WHERE po.docstatus = 1 AND po.order_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_014', 'PRC-014 Vendor On-time Delivery Rate (%)', 'Percentage of goods receipts delivered on or before promised PO delivery date Target: ≥ 95%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE g.receipt_date <= po.delivery_date)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt g JOIN reporting.purchase_order po ON po.name = g.purchase_order WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_015', 'PRC-015 Vendor In-full Delivery Rate (%)', 'Percentage of goods receipts meeting full ordered line quantity Target: ≥ 98%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE i.received_qty >= COALESCE(i.pending_qty, i.ordered_qty))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt_items i JOIN reporting.goods_receipt g ON g.name = i.parent WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_016', 'PRC-016 Vendor OTIF (On-Time In-Full) (%)', 'Supplier deliveries fulfilled completely and strictly on time Target: ≥ 92%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE g.receipt_date <= po.delivery_date AND NOT EXISTS (SELECT 1 FROM reporting.goods_receipt_items i WHERE i.parent = g.name AND i.received_qty < COALESCE(i.pending_qty, i.ordered_qty)))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt g JOIN reporting.purchase_order po ON po.name = g.purchase_order WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_017', 'PRC-017 Quality Rejection Rate (%)', 'Proportion of received goods rejected due to quality inspection failure Target: ≤ 1%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(COALESCE(i.rejected_qty, 0))) / NULLIF(SUM(COALESCE(i.received_qty, 0) + COALESCE(i.rejected_qty, 0)), 0), 2) AS value FROM reporting.goods_receipt_items i JOIN reporting.goods_receipt g ON g.name = i.parent WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_018', 'PRC-018 PO Lead Time (Days)', 'Average supplier fulfillment lead time in days from order to delivery Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(g.receipt_date - po.order_date), 1) AS value FROM reporting.goods_receipt g JOIN reporting.purchase_order po ON po.name = g.purchase_order WHERE g.docstatus = 1 AND g.receipt_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_019', 'PRC-019 Receipts Without Delivery Note (%)', 'Goods receipts submitted without supplier delivery note number or attachment Target: 0%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(delivery_note_no, '''') = '''')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.goods_receipt WHERE docstatus = 1 AND receipt_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_020', 'PRC-020 Active Vendors (Vendors)', 'Number of unique vendors with PO transactions in the last 12 months Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(DISTINCT vendor) AS value FROM reporting.purchase_order WHERE docstatus = 1 AND order_date > CURRENT_DATE - 365", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_prc_021', 'PRC-021 Vendors On Hold (Vendors)', 'Number of vendor master records blocked from purchasing transactions Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.vendor WHERE is_active AND on_hold", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Purchasing", "Finance"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_stk_004', 'STK-004 Stock Count Accuracy (%)', 'Percentage of stock items with zero physical count discrepancy Target: ≥ 98%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(i.qty_difference, 0) = 0)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.stock_reconciliation_items i JOIN reporting.stock_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Stock"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_stk_005', 'STK-005 Stock Take Variance Value (IDR)', 'Absolute monetary value of physical inventory count adjustments Target: ≤ 0.5% stock value. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(ABS(i.amount_difference)), 0) AS value FROM reporting.stock_reconciliation_items i JOIN reporting.stock_reconciliation r ON r.name = i.parent WHERE r.docstatus = 1 AND r.posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Stock"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_stk_010', 'STK-010 Stock Scrappage & Material Issues (IDR)', 'Value of non-sales inventory write-offs and internal consumption issues Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(total_value), 0) AS value FROM reporting.stock_entry WHERE docstatus = 1 AND purpose = ''Material Issue'' AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Stock"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_stk_011', 'STK-011 Inter-warehouse Transfers (IDR)', 'Value and volume of inventory transferred between internal warehouses Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.stock_entry WHERE docstatus = 1 AND purpose = ''Material Transfer'' AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Stock"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_stk_012', 'STK-012 Gross Margin by Item', 'Gross profit margin percentage achieved per inventory product item Target: —. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(i.item_name, i.item) AS label, ROUND(100.0 * SUM(i.amount - COALESCE(i.stock_amount, 0)) / NULLIF(SUM(i.amount), 0), 2) AS value FROM reporting.sales_invoice_items i JOIN reporting.sales_invoice si ON si.name = i.parent WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End AND COALESCE(i.stock_amount, 0) > 0 GROUP BY 1 ORDER BY SUM(i.amount) DESC LIMIT 15", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Stock"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_001', 'CRM-001 New Lead Volume (Leads)', 'Total number of new sales leads generated in the period Target: Per marketing target. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_002', 'CRM-002 Lead Conversion Rate (%)', 'Percentage of leads successfully converted to opportunities or customers Target: ≥ 15%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Converted'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_003', 'CRM-003 Lead Qualification Rate (%)', 'Percentage of leads qualifying as sales-ready (Qualified or Converted) Target: ≥ 30%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status IN (''Qualified'',''Converted''))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_004', 'CRM-004 Lead Response Time (Hours)', 'Average hours elapsed from lead creation to initial outreach activity Target: ≤ 24 hours. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(EXTRACT(EPOCH FROM (f.first_at - l.created)) / 3600.0)::numeric, 1) AS value FROM reporting.lead l JOIN (SELECT reference_name, MIN(start_at) AS first_at FROM reporting.activity WHERE reference_doctype = ''Lead'' AND status <> ''Cancelled'' GROUP BY 1) f ON f.reference_name = l.name WHERE l.created::date BETWEEN @Start AND @End AND f.first_at >= l.created", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_005', 'CRM-005 Time to Convert (Days)', 'Average days required from lead generation to formal conversion Target: ≤ 30 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(converted_on - created::date), 1) AS value FROM reporting.lead WHERE status = ''Converted'' AND converted_on BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_006', 'CRM-006 Leads by Source', 'Distribution and conversion efficiency analyzed across lead sources Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(lead_source, ''(blank)'') AS label, COUNT(*) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_007', 'CRM-007 Hot Lead Ratio (%)', 'Percentage of prospective leads categorized with Hot priority rating Target: —. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE rating = ''Hot'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_008', 'CRM-008 Unqualified Rate & Reasons', 'Distribution of disqualified leads analyzed by disqualification reason Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(disqualify_reason, ''(no reason)'') AS label, COUNT(*) AS value FROM reporting.lead WHERE created::date BETWEEN @Start AND @End AND status = ''Unqualified'' GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_009', 'CRM-009 Unassigned Leads (Leads)', 'Active prospects without an assigned sales representative owner Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.lead WHERE sales_rep IS NULL AND status IN (''New'',''Contacted'')", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_010', 'CRM-010 Marketing Campaign ROI (%)', 'Return on investment achieved from closed-won revenue against campaign cost Target: ≥ 300%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(won_amount) - SUM(actual_cost)) / NULLIF(SUM(actual_cost), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_011', 'CRM-011 Cost per Lead (CPL) (IDR)', 'Average marketing acquisition cost per generated lead Target: —. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(SUM(actual_cost) / NULLIF(SUM(lead_count), 0), 0) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_012', 'CRM-012 Campaign Budget Variance (%)', 'Percentage variance between actual campaign expenditure and budget Target: ± 10%. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(actual_cost) - SUM(budgeted_cost)) / NULLIF(SUM(budgeted_cost), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_013', 'CRM-013 Campaign Revenue Attainment (%)', 'Won opportunity revenue realized against initial campaign projection Target: ≥ 100%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(won_amount)) / NULLIF(SUM(expected_revenue), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_014', 'CRM-014 Campaign Lead-to-Opportunity Rate (%)', 'Proportion of campaign leads converted into formal sales opportunities Target: ≥ 20%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(opportunity_count)) / NULLIF(SUM(lead_count), 0), 2) AS value FROM reporting.campaign WHERE status <> ''Aborted'' AND start_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_015', 'CRM-015 Total Pipeline Value (IDR)', 'Total aggregate potential value of open sales opportunities Target: ≥ 3x quarterly quota. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(amount), 0) AS value FROM reporting.opportunity WHERE stage_type = ''Open''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_016', 'CRM-016 Weighted Pipeline Value (IDR)', 'Probability-weighted forecast value of open sales pipeline Target: ≥ quarterly quota. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(weighted_amount), 0) AS value FROM reporting.opportunity WHERE stage_type = ''Open''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_018', 'CRM-018 Opportunity Win Rate (%)', 'Percentage of closed opportunities won by deal count Target: ≥ 25%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE stage_type = ''Won'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_019', 'CRM-019 Win Rate by Value (%)', 'Percentage of closed opportunity value won in currency Target: ≥ 25%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(amount) FILTER (WHERE stage_type = ''Won'')) / NULLIF(SUM(amount), 0), 2) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_020', 'CRM-020 Average Deal Size (IDR)', 'Average monetary contract value of closed-won opportunities Target: Increase QoQ. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(amount), 0) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND stage_type = ''Won''", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_021', 'CRM-021 Sales Cycle Length (Days)', 'Average elapsed days from opportunity creation to Won closing date Target: ≤ 60 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(closed_date - created::date), 1) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND stage_type = ''Won''", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_022', 'CRM-022 Sales Velocity (IDR/day)', 'Expected revenue velocity ($/day = Opportunities × Win Rate × Deal Size / Cycle) Target: Increase QoQ. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "WITH c AS (SELECT COUNT(*) FILTER (WHERE stage_type = ''Won'')::numeric / NULLIF(COUNT(*), 0) AS win_rate, AVG(amount) FILTER (WHERE stage_type = ''Won'') AS deal, AVG(closed_date - created::date) FILTER (WHERE stage_type = ''Won'') AS cycle FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End) SELECT ROUND((SELECT COUNT(*) FROM reporting.opportunity WHERE stage_type = ''Open'') * c.win_rate * c.deal / NULLIF(c.cycle, 0), 0) AS value FROM c", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_023', 'CRM-023 Stale Opportunities (Opportunities)', 'Open opportunities with no activity or updates beyond configured threshold Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.opportunity WHERE stage_type = ''Open'' AND modified < now() - make_interval(days => COALESCE((SELECT MAX(stale_opportunity_days) FROM reporting.crmsettings), 30)::int)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_024', 'CRM-024 Overdue Close Date Opportunities (Opportunities)', 'Open sales opportunities where target close date has expired Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.opportunity WHERE stage_type = ''Open'' AND expected_close_date < CURRENT_DATE", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_025', 'CRM-025 Lost Deal Reason Analysis', 'Distribution of lost opportunities categorized by primary lost reason Target: —. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(lost_reason, ''(no reason)'') AS label, COUNT(*) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND stage_type = ''Lost'' GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_026', 'CRM-026 Competitive Win Rate (%)', 'Win rate achieved on competitive deals with named rivals involved Target: —. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE stage_type = ''Won'')) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.opportunity WHERE stage_type IN (''Won'',''Lost'') AND closed_date BETWEEN @Start AND @End AND COALESCE(competitor, '''') <> ''''", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_028', 'CRM-028 Forecast Category Mix', 'Pipeline value distribution across forecast tiers (Commit / Best Case / Pipeline) Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(forecast_category, ''(blank)'') AS label, SUM(amount) AS value FROM reporting.opportunity WHERE stage_type = ''Open'' GROUP BY 1 ORDER BY 2 DESC", "parameters": [], "visual": {"type": "pie", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_029', 'CRM-029 Buying Committee Multithreading (%)', 'Percentage of open enterprise deals with two or more stakeholder contact roles Target: ≥ 70%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE (SELECT COUNT(*) FROM reporting.opportunity_contact_roles r WHERE r.parent = o.name) >= 2)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.opportunity o WHERE o.stage_type = ''Open''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_030', 'CRM-030 Quote-to-Order Conversion (%)', 'Percentage of customer quotations converted into confirmed sales orders Target: ≥ 40%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM reporting.sales_order so WHERE so.quotation = q.name AND so.docstatus = 1))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.quotation q WHERE q.workflow_state NOT IN (''Draft'',''Cancelled'') AND q.quotation_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_031', 'CRM-031 Expired Quotations (Quotations)', 'Quotations past valid-until date without customer acceptance or order Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.quotation WHERE workflow_state = ''Expired'' OR (workflow_state = ''Sent'' AND valid_until < CURRENT_DATE)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_032', 'CRM-032 Average Quotation Discount (%)', 'Average percentage discount extended on quotation line items Target: ≤ discount policy. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(COALESCE(i.discount_percent, 0)), 2) AS value FROM reporting.quotation_items i JOIN reporting.quotation q ON q.name = i.parent WHERE q.workflow_state NOT IN (''Draft'',''Cancelled'') AND q.quotation_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_034', 'CRM-034 Time to Quote (Days)', 'Days required from opportunity discovery to initial quote presentation Target: ≤ 3 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(f.first_q - o.created::date), 1) AS value FROM reporting.opportunity o JOIN (SELECT opportunity, MIN(quotation_date) AS first_q FROM reporting.quotation WHERE workflow_state <> ''Cancelled'' AND opportunity IS NOT NULL GROUP BY 1) f ON f.opportunity = o.name WHERE f.first_q BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_035', 'CRM-035 Bookings (Sales Order Value) (IDR)', 'Total gross monetary bookings confirmed via submitted sales orders Target: Per target. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(total), 0) AS value FROM reporting.sales_order WHERE docstatus = 1 AND order_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_036', 'CRM-036 Sales Order Backlog (Unbilled) (IDR)', 'Confirmed customer order value pending final billing fulfillment Target: —. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(grand_total - COALESCE(billed_amount, 0)), 0) AS value FROM reporting.sales_order WHERE docstatus = 1 AND billing_status <> ''Fully billed''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_037', 'CRM-037 Order-to-Invoice Cycle Time (Days)', 'Average days between sales order confirmation and primary invoice issuance Target: ≤ 7 days. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(AVG(f.first_inv - so.order_date), 1) AS value FROM reporting.sales_order so JOIN (SELECT sales_order, MIN(posting_date) AS first_inv FROM reporting.sales_invoice WHERE docstatus = 1 AND sales_order IS NOT NULL GROUP BY 1) f ON f.sales_order = so.name WHERE so.docstatus = 1 AND f.first_inv BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_039', 'CRM-039 Sales Revenue by Representative', 'Net invoiced sales volume achieved per individual sales representative Target: Per sales quota. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(si.sales_rep, ''(no sales)'') AS label, ROUND(SUM(si.total * si.exchange_rate), 0) AS value FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_040', 'CRM-040 Sales Revenue by Territory', 'Invoiced sales performance distributed across geographic territories Target: —. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(c.territory, ''(no territory)'') AS label, ROUND(SUM(si.total * si.exchange_rate), 0) AS value FROM reporting.sales_invoice si LEFT JOIN reporting.customer c ON c.name = si.customer WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_041', 'CRM-041 Active Customer Count (Customers)', 'Number of unique customer accounts with invoice activity in the last 12 months Target: Increase YoY. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(DISTINCT customer) AS value FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date > CURRENT_DATE - 365", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_042', 'CRM-042 New Customer Acquisition (Customers)', 'First-time purchasing customer logos acquiring their inaugural invoice Target: Per target. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM (SELECT customer, MIN(posting_date) AS first_inv FROM reporting.sales_invoice WHERE docstatus = 1 GROUP BY 1) f WHERE f.first_inv BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_043', 'CRM-043 Customer Retention Rate (%)', 'Percentage of prior-year active customer accounts retained this year Target: ≥ 85%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE customer IN (SELECT customer FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End))) / NULLIF(COUNT(*), 0), 2) AS value FROM (SELECT DISTINCT customer FROM reporting.sales_invoice WHERE docstatus = 1 AND posting_date >= @Start::date - 365 AND posting_date < @Start) prev", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_044', 'CRM-044 Top 10 Customer Revenue Concentration (%)', 'Share of total company revenue contributed by top 10 customer accounts Target: ≤ 40%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "WITH c AS (SELECT si.customer, SUM(si.total * si.exchange_rate) AS s FROM reporting.sales_invoice si WHERE si.docstatus = 1 AND si.posting_date BETWEEN @Start AND @End GROUP BY 1) SELECT ROUND(100.0 * (SELECT SUM(s) FROM (SELECT s FROM c ORDER BY s DESC LIMIT 10) t) / NULLIF((SELECT SUM(s) FROM c), 0), 2) AS value", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_045', 'CRM-045 Active Contract Value (ACV) (IDR)', 'Total aggregate annualized monetary value of active customer contracts Target: —. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(contract_value), 0) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND contract_status IN (''Active'',''Expiring soon'')", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_046', 'CRM-046 Expiring Customer Contracts (Contracts)', 'Active revenue contracts scheduled to terminate within advance notice window Target: All contacted. Direction: Range. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND contract_status IN (''Active'',''Expiring soon'') AND end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + COALESCE(notice_days, 30)::int", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_047', 'CRM-047 Customer Contract Renewal Rate (%)', 'Percentage of concluding customer contracts successfully renewed Target: ≥ 85%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE contract_status = ''Renewed'')) / NULLIF(COUNT(*) FILTER (WHERE contract_status IN (''Renewed'',''Expired'')), 0), 2) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND end_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_048', 'CRM-048 Contract Revenue Churn Rate (%)', 'Annualized recurring contract value lost through expiration or cancellation Target: ≤ 10%. Direction: Down. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(contract_value) FILTER (WHERE contract_status IN (''Expired'',''Cancelled''))) / NULLIF(SUM(contract_value), 0), 2) AS value FROM reporting.customer_contract WHERE docstatus IN (1, 2) AND end_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_049', 'CRM-049 Auto-renewal Contract Ratio (%)', 'Percentage of customer service contracts containing evergreen auto-renewal clauses Target: —. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE auto_renew)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.customer_contract WHERE docstatus = 1 AND contract_status IN (''Active'',''Expiring soon'')", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_050', 'CRM-050 Activities per Sales Representative', 'Completed customer touchpoints (meetings, calls, tasks) per sales rep Target: ≥ 40/week. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(assigned_to, ''(unassigned)'') AS label, COUNT(*) AS value FROM reporting.activity WHERE status = ''Completed'' AND start_at::date BETWEEN @Start AND @End GROUP BY 1 ORDER BY 2 DESC LIMIT 15", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "bar", "xColumn": "label", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_051', 'CRM-051 Sales Activity Completion Rate (%)', 'Proportion of scheduled sales activities executed to completion Target: ≥ 90%. Direction: Up. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE status = ''Completed'')) / NULLIF(COUNT(*) FILTER (WHERE status = ''Completed'' OR (status = ''Planned'' AND COALESCE(end_at, start_at) < now())), 0), 2) AS value FROM reporting.activity WHERE start_at::date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_052', 'CRM-052 Overdue Sales Activities (Activities)', 'Planned customer engagement activities past scheduled execution deadline Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.activity WHERE status = ''Planned'' AND COALESCE(end_at, start_at) < now()", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_053', 'CRM-053 Total Sales Commission Earned (IDR)', 'Total sales commission compensation earned across sales teams in period Target: Per plan. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT COALESCE(SUM(total_commission), 0) AS value FROM reporting.commission_statement WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_crm_054', 'CRM-054 Commission as % of Revenue (%)', 'Sales commissions earned compared to qualifying revenue base Target: Per commission rate plan. Direction: Range. Period follows dashboard date filter (@Start/@End).', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (SUM(total_commission)) / NULLIF(SUM(total_base), 0), 2) AS value FROM reporting.commission_statement WHERE docstatus = 1 AND posting_date BETWEEN @Start AND @End", "parameters": [{"name": "Start", "label": "Start date", "type": "date", "defaultValue": "2026-01-01", "binding": "global:start"}, {"name": "End", "label": "End date", "type": "date", "defaultValue": "2026-12-31", "binding": "global:end"}], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Sales", "Manager"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_001', 'MDM-001 Customer Master Completeness (%)', 'Active customer accounts with tax ID, primary address, contact, and payment terms Target: ≥ 98%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(tax_id, '''') <> '''' AND primary_address IS NOT NULL AND primary_contact IS NOT NULL AND payment_term IS NOT NULL)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.customer WHERE is_active", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_002', 'MDM-002 Vendor Master Completeness (%)', 'Active supplier records with tax ID, verified bank details, and payment terms Target: ≥ 98%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE COALESCE(tax_id, '''') <> '''' AND payment_term IS NOT NULL AND EXISTS (SELECT 1 FROM reporting.vendor_bank_accounts b WHERE b.parent = v.name))) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.vendor v WHERE v.is_active", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_003', 'MDM-003 Duplicate Customer / Vendor Records (Records)', 'Potential duplicate master records identified by shared tax ID or legal name Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT (SELECT COUNT(*) FROM (SELECT tax_id FROM reporting.customer WHERE COALESCE(tax_id, '''') <> '''' AND NOT COALESCE(is_internal_customer, false) GROUP BY 1 HAVING COUNT(*) > 1) a) + (SELECT COUNT(*) FROM (SELECT tax_id FROM reporting.vendor WHERE COALESCE(tax_id, '''') <> '''' AND NOT COALESCE(is_internal_vendor, false) GROUP BY 1 HAVING COUNT(*) > 1) b) AS value", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_004', 'MDM-004 Items Without Default Accounting Accounts (Items)', 'Active items missing assigned income or expense accounts on item and group levels Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.item i LEFT JOIN reporting.item_group g ON g.name = i.item_group WHERE i.is_active AND ((i.is_sales_item AND COALESCE(i.income_account, g.income_account) IS NULL) OR (i.is_purchase_item AND COALESCE(i.expense_account, g.expense_account) IS NULL))", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_005', 'MDM-005 Expired Item Price Lists (Prices)', 'Active price list rates where valid-to date expired without successor pricing Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.item_price p WHERE p.valid_to < CURRENT_DATE AND NOT EXISTS (SELECT 1 FROM reporting.item_price n WHERE n.item = p.item AND n.price_list = p.price_list AND COALESCE(n.valid_to, DATE ''9999-12-31'') >= CURRENT_DATE)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_006', 'MDM-006 Stock Items Without Default Warehouse (Items)', 'Inventory items missing an assigned default operating storage warehouse Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.item WHERE is_active AND is_stock_item AND default_warehouse IS NULL", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_007', 'MDM-007 Incomplete Contact Records (Contacts)', 'Active business contacts missing both email address and phone number Target: 0. Direction: Down. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.contact WHERE is_active AND COALESCE(email, '''') = '''' AND COALESCE(mobile, '''') = ''''", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_008', 'MDM-008 Current Fiscal Year Holiday List (Yes/No)', 'Operational calendar verification confirming holiday list covers current fiscal year Target: Available before Jan 1. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT COUNT(*) AS value FROM reporting.holiday_list WHERE from_date <= make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 1, 1) AND to_date >= make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 12, 31)", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
INSERT INTO frogframe_dashboard_widgets (tenant_id, id, name, description, config, created_by, created_at, updated_at, version) VALUES (:'tenant', 'w_kpi_mdm_009', 'MDM-009 Valid Payment Terms Configuration (%)', 'Active payment terms verified where schedule portions total exactly 100% Target: 100%. Direction: Up. Current snapshot; not affected by date filters.', '{"schemaVersion": 1, "sql": "SELECT ROUND(100.0 * (COUNT(*) FILTER (WHERE total_portion = 100)) / NULLIF(COUNT(*), 0), 2) AS value FROM reporting.payment_term WHERE is_active", "parameters": [], "visual": {"type": "number", "yColumns": ["value"]}, "roles": ["Finance", "Purchasing", "Sales"]}'::jsonb, :'owner', now(), now(), 1) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, updated_at = now(), version = frogframe_dashboard_widgets.version + 1;
