INSERT INTO frogframe_dashboards (tenant_id, id, name, description, owner_id, is_shared, is_default, roles, layout, created_at, updated_at) VALUES (:'tenant', 'd_kpi_hr_kontrak_kerja', 'KPI HR · Employment Contracts', '3 KPIs from the FrogFrame KPI catalog (HR).', :'owner', true, false, '["HR"]'::jsonb, '{"items": [{"widgetId": "w_kpi_hr_034", "span": 1}, {"widgetId": "w_kpi_hr_035", "span": 1}, {"widgetId": "w_kpi_hr_036", "span": 1}]}'::jsonb, now(), now()) ON CONFLICT (tenant_id, id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, roles = EXCLUDED.roles, layout = EXCLUDED.layout, updated_at = now();
